import { jsx as _jsx } from "react/jsx-runtime";
import { getAllPathsInDecoratedNav, getAllPathsInDocsNav } from '@mintlify/common';
import { prebuild } from '@mintlify/prebuild';
import AdmZip from 'adm-zip';
import express from 'express';
import fse, { pathExists } from 'fs-extra';
import { createServer } from 'http';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';
import { CLIENT_PATH, CMD_EXEC_PATH, VERSION_PATH, NEXT_PUBLIC_PATH, NEXT_PROPS_PATH, PREVIEW_PATH, configureSharedPreviewPath, } from '../constants.js';
import { addLog, clearLogs } from '../logging-state.js';
import { ErrorLog, SpinnerLog, SuccessLog, WarningLog } from '../logs.js';
import { localizeAssets } from './export-assets.js';
import { applyBasePathToExport, findBasePathConflict, normalizeExportBasePath, } from './export-base-path.js';
import { generateExportLlmsTxt } from './export-llms.js';
import { writeSearchIndex } from './export-search.js';
import { getGroupFilteredRoutes } from './getGroupFilteredRoutes.js';
import { isOnline } from './is-online.js';
import { setupNext } from './setupNext.js';
import { silentUpdateClient } from './update.js';
const CONCURRENCY = 10;
const RSC_CONTENT_TYPE = 'text/x-component';
const RSC_PAYLOAD_FILE = 'index.txt';
const EXPORT_SCRIPTS_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..', 'export-scripts');
function resolveRequestRoute(route, rootRoute) {
    if (route === '/' && rootRoute)
        return rootRoute;
    return route;
}
function prepareRoutesForExport(routes, groups) {
    if (!groups?.length || routes.includes('/'))
        return { routes };
    const firstAccessibleRoute = routes.find((route) => route !== '/');
    if (!firstAccessibleRoute)
        return { routes };
    return {
        routes: ['/', ...routes],
        rootRoute: firstAccessibleRoute,
    };
}
const INDEX_SUFFIX = '/index';
export const withIndexRouteAliases = (routes) => [
    ...new Set(routes.flatMap((route) => route.endsWith(INDEX_SUFFIX) ? [route, route.slice(0, -INDEX_SUFFIX.length) || '/'] : [route])),
];
async function withExportConsoleSilenced(task) {
    const originalConsole = {
        log: console.log,
        warn: console.warn,
    };
    const noop = (..._args) => undefined;
    console.log = noop;
    console.warn = noop;
    try {
        return await task();
    }
    finally {
        console.log = originalConsole.log;
        console.warn = originalConsole.warn;
    }
}
async function fatal(message) {
    clearLogs();
    addLog(_jsx(ErrorLog, { message: message }));
    await new Promise((resolve) => setTimeout(resolve, 50));
    process.exit(1);
}
async function collectRoutes(groups) {
    const shouldFilterByGroups = groups !== undefined && groups.length > 0;
    const routes = new Set(shouldFilterByGroups ? [] : ['/']);
    const docsConfigPath = path.join(CMD_EXEC_PATH, 'docs.json');
    if (!(await pathExists(docsConfigPath))) {
        return [...routes];
    }
    const config = await fse.readJson(docsConfigPath);
    if (!shouldFilterByGroups && config.navigation) {
        for (const navPath of getAllPathsInDocsNav(config.navigation)) {
            routes.add(`/${navPath}`);
        }
    }
    // Also collect routes from the generated decorated nav, which includes OpenAPI/AsyncAPI
    // pages and filters to real page entries (ignoring non-page hrefs in nav divisions).
    const generatedNavPath = path.join(NEXT_PROPS_PATH, 'generatedDocsNav.json');
    if (await pathExists(generatedNavPath)) {
        const generatedNav = await fse.readJson(generatedNavPath);
        if (shouldFilterByGroups)
            return getGroupFilteredRoutes(generatedNav, groups);
        for (const navPath of getAllPathsInDecoratedNav(generatedNav)) {
            routes.add(`/${navPath}`);
        }
    }
    else if (shouldFilterByGroups) {
        throw new Error('failed to collect group-filtered routes');
    }
    return [...routes];
}
export async function generatePages(baseUrl, routes, outputDir, rootRoute) {
    const queue = [...routes];
    let failedPageCount = 0;
    async function worker() {
        while (queue.length > 0) {
            const route = queue.shift();
            try {
                const requestRoute = resolveRequestRoute(route, rootRoute);
                const [res, rscRes] = await Promise.all([
                    fetch(`${baseUrl}${requestRoute}`),
                    fetch(`${baseUrl}${requestRoute}`, { headers: { RSC: '1' } }),
                ]);
                const isRscPayload = rscRes.headers.get('content-type')?.startsWith(RSC_CONTENT_TYPE);
                if (!res.ok || !rscRes.ok || !isRscPayload) {
                    failedPageCount += 1;
                    addLog(_jsx(ErrorLog, { message: `failed to generate ${route} (status ${res.ok ? rscRes.status : res.status})` }));
                    continue;
                }
                const pageDir = route === '/' ? outputDir : path.join(outputDir, route);
                await fse.ensureDir(pageDir);
                await Promise.all([
                    fse.writeFile(path.join(pageDir, 'index.html'), await res.text(), 'utf8'),
                    fse.writeFile(path.join(pageDir, RSC_PAYLOAD_FILE), await rscRes.text(), 'utf8'),
                ]);
            }
            catch (err) {
                failedPageCount += 1;
                addLog(_jsx(ErrorLog, { message: `failed to generate ${route}: ${err instanceof Error ? err.message : 'unknown error'}` }));
            }
        }
    }
    await Promise.all(Array.from({ length: Math.min(CONCURRENCY, routes.length) }, () => worker()));
    return failedPageCount;
}
async function startServer(basePath) {
    const app = express();
    const requestHandler = await setupNext(basePath ? { assetPrefix: basePath } : undefined);
    app.use('/', express.static(NEXT_PUBLIC_PATH));
    app.all('*', (req, res) => requestHandler(req, res));
    const server = createServer(app);
    const port = await new Promise((resolve, reject) => {
        server.once('error', reject);
        server.listen(0, () => {
            const addr = server.address();
            if (!addr || typeof addr === 'string') {
                reject(new Error('failed to determine listening port'));
                return;
            }
            resolve(addr.port);
        });
    });
    return { server, port };
}
export async function writeStaticUserInfo(tmpDir, groups) {
    if (!groups?.length)
        return;
    await fse.outputJson(path.join(tmpDir, '_mintlify', 'api', 'user', 'index.html'), {
        user: { groups },
    });
}
async function bundleStaticAssets(tmpDir, groups, basePath) {
    const nextStaticSrc = path.join(CLIENT_PATH, '.next', 'static');
    if (await pathExists(nextStaticSrc)) {
        await fse.copy(nextStaticSrc, path.join(tmpDir, '_next', 'static'));
    }
    if (await pathExists(NEXT_PUBLIC_PATH)) {
        const publicFiles = await fse.readdir(NEXT_PUBLIC_PATH);
        for (const file of publicFiles) {
            await fse.copy(path.join(NEXT_PUBLIC_PATH, file), path.join(tmpDir, file), {
                overwrite: false,
            });
        }
    }
    await writeStaticUserInfo(tmpDir, groups);
    const serveScript = await fse.readFile(path.join(EXPORT_SCRIPTS_DIR, 'serve.js'), 'utf8');
    await fse.writeFile(path.join(tmpDir, 'serve.js'), serveScript.replace("const BASE_PATH = '';", `const BASE_PATH = ${JSON.stringify(basePath)};`));
    await fse.copy(path.join(EXPORT_SCRIPTS_DIR, 'README.md'), path.join(tmpDir, 'README.md'));
    await fse.copy(path.join(EXPORT_SCRIPTS_DIR, 'start-docs.sh'), path.join(tmpDir, 'Start Docs.command'));
    await fse.copy(path.join(EXPORT_SCRIPTS_DIR, 'start-docs.bat'), path.join(tmpDir, 'Start Docs.bat'));
}
export async function writeLlmsTxt(tmpDir, routes, basePath = '') {
    const llmsTxtPath = path.join(tmpDir, 'llms.txt');
    if (await pathExists(llmsTxtPath))
        return;
    const [docsConfig, generatedNav] = await Promise.all([
        fse.readJson(path.join(NEXT_PROPS_PATH, 'docs.json')).catch(() => undefined),
        fse.readJson(path.join(NEXT_PROPS_PATH, 'generatedDocsNav.json')).catch(() => undefined),
    ]);
    await fse.writeFile(llmsTxtPath, generateExportLlmsTxt(docsConfig, generatedNav, routes, basePath), 'utf8');
}
async function closeServer(server) {
    await new Promise((resolve) => {
        server.close(() => resolve());
    });
}
async function generateExportArchive(routes, outputPath, groups, basePath) {
    const { server, port } = await startServer(basePath);
    const { routes: preparedRoutes, rootRoute } = prepareRoutesForExport(routes, groups);
    const routesToGenerate = withIndexRouteAliases(preparedRoutes);
    let tmpDir;
    try {
        clearLogs();
        addLog(_jsx(SpinnerLog, { message: `generating ${routesToGenerate.length} pages...` }));
        tmpDir = await fse.mkdtemp(path.join(os.tmpdir(), 'mint-export-'));
        const exportDir = tmpDir;
        const failedPageCount = await withExportConsoleSilenced(async () => {
            return generatePages(`http://localhost:${port}`, routesToGenerate, exportDir, rootRoute);
        });
        if (failedPageCount > 0) {
            throw new Error(`failed to export: ${failedPageCount} page(s) could not be generated.`);
        }
        addLog(_jsx(SpinnerLog, { message: "collecting static assets..." }));
        await bundleStaticAssets(exportDir, groups, basePath);
        await applyBasePathToExport(exportDir, basePath);
        await writeLlmsTxt(exportDir, routes, basePath);
        addLog(_jsx(SpinnerLog, { message: "building search index..." }));
        const [docsConfig, generatedNav] = await Promise.all([
            fse.readJson(path.join(NEXT_PROPS_PATH, 'docs.json')).catch(() => undefined),
            fse.readJson(path.join(NEXT_PROPS_PATH, 'generatedDocsNav.json')).catch(() => undefined),
        ]);
        await writeSearchIndex(exportDir, { generatedNav, docsConfig, groups });
        addLog(_jsx(SpinnerLog, { message: "bundling external assets..." }));
        const { failed } = await localizeAssets(exportDir);
        addLog(_jsx(SpinnerLog, { message: "creating zip archive..." }));
        const zip = new AdmZip();
        zip.addLocalFolder(exportDir);
        zip.writeZip(outputPath);
        clearLogs();
        for (const url of failed) {
            addLog(_jsx(WarningLog, { message: `could not bundle ${url}` }));
        }
        addLog(_jsx(SuccessLog, { message: `exported to ${outputPath}` }));
    }
    finally {
        if (tmpDir) {
            await fse.remove(tmpDir);
        }
        await closeServer(server);
    }
}
export const exportSite = async (argv) => {
    configureSharedPreviewPath();
    const hasInternet = await isOnline();
    const clientVersion = argv['client-version'];
    const localClientVersion = argv['local-client-version'];
    const groups = argv.groups;
    let basePath = '';
    try {
        basePath = normalizeExportBasePath(argv.basePath);
    }
    catch (err) {
        await fatal(err instanceof Error ? err.message : 'invalid base path');
    }
    const cliVersion = argv.cliVersion;
    const disableOpenApi = argv.disableOpenapi;
    const outputPath = path.resolve(argv.output);
    await fse.ensureDir(PREVIEW_PATH);
    const versionString = (await pathExists(VERSION_PATH))
        ? fse.readFileSync(VERSION_PATH, 'utf8')
        : null;
    if (!versionString && !localClientVersion && !hasInternet) {
        await fatal('export requires an internet connection on first run.');
    }
    addLog(_jsx(SpinnerLog, { message: "preparing export..." }));
    const { error } = await silentUpdateClient({
        versionString,
        clientVersion,
        cliVersion,
        localClientVersion,
    });
    if (error)
        await fatal(error);
    try {
        fse.emptyDirSync(NEXT_PUBLIC_PATH);
        fse.emptyDirSync(NEXT_PROPS_PATH);
    }
    catch (err) {
        await fatal(err instanceof Error && err.message ? err.message : 'failed to prepare export directories');
    }
    process.chdir(CLIENT_PATH);
    addLog(_jsx(SpinnerLog, { message: "running prebuild..." }));
    try {
        await withExportConsoleSilenced(async () => {
            await prebuild(CMD_EXEC_PATH, { groups, disableOpenApi });
        });
    }
    catch (err) {
        await fatal(err instanceof Error && err.message ? err.message : 'prebuild step failed');
    }
    let routes = [];
    try {
        routes = await collectRoutes(groups);
    }
    catch (err) {
        await fatal(err instanceof Error && err.message ? err.message : 'failed to collect routes');
    }
    const conflictingRoute = findBasePathConflict(routes, basePath);
    if (conflictingRoute) {
        await fatal(`--base-path ${basePath} conflicts with the page ${conflictingRoute}. Pages can't start with the base path, so pick a different one.`);
    }
    addLog(_jsx(SpinnerLog, { message: "starting local server..." }));
    process.env.MINT_EXPORT = JSON.stringify({ groups, basePath: basePath || undefined });
    try {
        await generateExportArchive(routes, outputPath, groups, basePath);
    }
    catch (err) {
        await fatal(err instanceof Error && err.message ? err.message : 'export failed');
    }
};
